protocol InstrumentControl {
  // States
  state SystemIdle
  state InstrumentStarting
  state InstrumentReady
  state InstrumentShuttingDown
  state SelfTesting
  state Configuring
  state DynamicReconfiguring
  state StatusReporting

  // Transitions
  SystemIdle --START_INSTRUMENT--> InstrumentStarting
  InstrumentStarting --ACK_START--> InstrumentReady
  InstrumentReady --SHUTDOWN_INSTRUMENT--> InstrumentShuttingDown
  InstrumentShuttingDown --ACK_SHUTDOWN--> SystemIdle
  InstrumentReady --SELF_TEST--> SelfTesting
  SelfTesting --SELF_TEST_RESULT--> InstrumentReady
  InstrumentReady --CONFIGURE--> Configuring
  Configuring --CONFIGURE_ACK--> InstrumentReady
  InstrumentReady --DYNAMIC_RECONFIG--> DynamicReconfiguring
  DynamicReconfiguring --DYNAMIC_RECONFIG_ACK--> InstrumentReady
  InstrumentReady --STATUS_QUERY--> StatusReporting
  StatusReporting --STATUS_RESPONSE--> InstrumentReady

  // Error handling: any command received in an invalid state results in ERROR
  SystemIdle --SHUTDOWN_INSTRUMENT--> ERROR
  SystemIdle --SELF_TEST--> ERROR
  SystemIdle --CONFIGURE--> ERROR
  SystemIdle --DYNAMIC_RECONFIG--> ERROR
  SystemIdle --STATUS_QUERY--> ERROR
  InstrumentStarting --SELF_TEST--> ERROR
  InstrumentStarting --CONFIGURE--> ERROR
  InstrumentStarting --DYNAMIC_RECONFIG--> ERROR
  InstrumentStarting --STATUS_QUERY--> ERROR
  InstrumentShuttingDown --START_INSTRUMENT--> ERROR
  InstrumentShuttingDown --SELF_TEST--> ERROR
  InstrumentShuttingDown --CONFIGURE--> ERROR
  InstrumentShuttingDown --DYNAMIC_RECONFIG--> ERROR
  InstrumentShuttingDown --STATUS_QUERY--> ERROR
  SelfTesting --START_INSTRUMENT--> ERROR
  SelfTesting --SHUTDOWN_INSTRUMENT--> ERROR
  SelfTesting --CONFIGURE--> ERROR
  SelfTesting --DYNAMIC_RECONFIG--> ERROR
  SelfTesting --STATUS_QUERY--> ERROR
  Configuring --START_INSTRUMENT--> ERROR
  Configuring --SHUTDOWN_INSTRUMENT--> ERROR
  Configuring --SELF_TEST--> ERROR
  Configuring --DYNAMIC_RECONFIG--> ERROR
  Configuring --STATUS_QUERY--> ERROR
  DynamicReconfiguring --START_INSTRUMENT--> ERROR
  DynamicReconfiguring --SHUTDOWN_INSTRUMENT--> ERROR
  DynamicReconfiguring --SELF_TEST--> ERROR
  DynamicReconfiguring --CONFIGURE--> ERROR
  DynamicReconfiguring --STATUS_QUERY--> ERROR
  StatusReporting --START_INSTRUMENT--> ERROR
  StatusReporting --SHUTDOWN_INSTRUMENT--> ERROR
  StatusReporting --SELF_TEST--> ERROR
  StatusReporting --CONFIGURE--> ERROR
  StatusReporting --DYNAMIC_RECONFIG--> ERROR

  // Test cases
  // TC-001: Positive instrument startup and shutdown
  // TC-002: Negative shutdown before startup
  // TC-003: Positive self-test
  // TC-004: Negative self-test during startup
  // TC-005: Positive configuration
  // TC-006: Boundary configuration parameters
  // TC-007: Positive dynamic reconfiguration
  // TC-008: Negative dynamic reconfiguration before startup
  // TC-009: Positive status query
  // TC-010: Negative status query during startup
}
```

